module consistency_checker (\n    input clk,\n    input rst_n,\n    input start,\n    input statement_valid,\n    input last,\n    input statement_type,\n    input [2:0] word1,\n    input [2:0] word2,\n    output reg ready,\n    output reg done,\n    output reg result\n);\n\nparameter MAX_WORDS = 8;\n\nlocalparam [2:0] IDLE    = 3'b000;\nlocalparam [2:0] FETCH   = 3'b001;\nlocalparam [2:0] FIND_X  = 3'b010;\nlocalparam [2:0] FIND_Y  = 3'b011;\nlocalparam [2:0] CHECK   = 3'b100;\nlocalparam [2:0] UPDATE  = 3'b101;\nlocalparam [2:0] DONE_ST = 3'b110;\n\nreg [2:0] state;\nreg [2:0] parent [0:MAX_WORDS-1];\nreg [MAX_WORDS-1:0] not_matrix [0:MAX_WORDS-1];\nreg contradiction_found;\nreg [2:0] root_x_reg, root_y_reg;\nreg current_type;\nreg current_last;\nreg [2:0] current_word1, current_word2;\ninteger i;\n\nfunction automatic [2:0] find_root;\n    input [2:0] x;\n    begin\n        find_root = x;\n        while (parent[find_root] != find_root) begin\n            find_root = parent[find_root];\n        end\n    end\nendfunction\n\nwire [2:0] root_x_wire = find_root(current_word1);\nwire [2:0] root_y_wire = find_root(current_word2);\n\nwire contradiction_is;\ngenerate\n    genvar i, j;\n    wire [MAX_WORDS-1:0] set_x_mask, set_y_mask;\n    for (i=0; i<MAX_WORDS; i=i+1) begin : gen_mask\n        assign set_x_mask[i] = (parent[i] == root_x_reg);\n        assign set_y_mask[i] = (parent[i] == root_y_reg);\n    end\n    wire [MAX_WORDS-1:0] conflict_check;\n    for (i=0; i<MAX_WORDS; i=i+1) begin : gen_conflict\n        assign conflict_check[i] = set_x_mask[i] && (|(not_matrix[i] & set_y_mask));\n    end\n    assign contradiction_is = |conflict_check;\nendgenerate\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        ready <= 1'b0;\n        done <= 1'b0;\n        result <= 1'b0;\n        contradiction_found <= 1'b0;\n        root_x_reg <= 3'b0;\n        root_y_reg <= 3'b0;\n        current_type <= 1'b0;\n        current_last <= 1'b0;\n        current_word1 <= 3'b0;\n        current_word2 <= 3'b0;\n        for (i=0; i<MAX_WORDS; i=i+1) begin\n            parent[i] <= i[2:0];\n            not_matrix[i] <= {MAX_WORDS{1'b0}};\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= FETCH;\n                    ready <= 1'b1;\n                    contradiction_found <= 1'b0;\n                end\n            end\n            \n            FETCH: begin\n                if (statement_valid) begin\n                    current_type <= statement_type;\n                    current_word1 <= word1;\n                    current_word2 <= word2;\n                    current_last <= last;\n                    ready <= 1'b0;\n                    state <= FIND_X;\n                end\n            end\n            \n            FIND_X: begin\n                root_x_reg <= root_x_wire;\n                state <= FIND_Y;\n            end\n            \n            FIND_Y: begin\n                root_y_reg <= root_y_wire;\n                state <= CHECK;\n            end\n            \n            CHECK: begin\n                if (current_type == 1'b0) begin\n                    if (contradiction_is) begin\n                        contradiction_found <= 1'b1;\n                    end\n                end else begin\n                    if (root_x_reg == root_y_reg) begin\n                        contradiction_found <= 1'b1;\n                    end\n                end\n                state <= UPDATE;\n            end\n            \n            UPDATE: begin\n                if (!contradiction_found) begin\n                    if (current_type == 1'b0) begin\n                        parent[root_x_reg] <= root_y_reg;\n                    end else begin\n                        not_matrix[current_word1][current_word2] <= 1'b1;\n                        not_matrix[current_word2][current_word1] <= 1'b1;\n                    end\n                end\n                \n                if (current_last) begin\n                    state <= DONE_ST;\n                end else begin\n                    ready <= 1'b1;\n                    state <= FETCH;\n                end\n            end\n            \n            DONE_ST: begin\n                done <= 1'b1;\n                result <= !contradiction_found;\n                state <= IDLE;\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule